#include "zlang/Lexer.h"
#include <cctype>
#include <unordered_map>
namespace zlang {Lexer::Lexer(std::string f,std::string s,Diagnostics&d):file_(std::move(f)),src_(std::move(s)),d_(d){if(src_.rfind("\xEF\xBB\xBF",0)==0)src_.erase(0,3);}char Lexer::peek(std::size_t n)const{return i_+n<src_.size()?src_[i_+n]:'\0';}char Lexer::take(){char c=peek();if(c){++i_;if(c=='\n'){++line_;col_=1;}else ++col_;}return c;}void Lexer::token(TokenKind k,std::size_t s,SourceLocation b){out_.push_back({k,src_.substr(s,i_-s),{b,{file_,i_,line_,col_}}});}void Lexer::stringToken(std::size_t s,SourceLocation b){take();std::string v;while(peek()&&peek()!='"'&&peek()!='\n'){char c=take();if(c=='\\'){char e=take();switch(e){case'n':v+='\n';break;case'r':v+='\r';break;case't':v+='\t';break;case'\\':v+='\\';break;case'"':v+='"';break;case'0':v+='\0';break;default:d_.error({b,{file_,i_,line_,col_}},"unknown escape sequence");}}else v+=c;}if(peek()!='"'){d_.error({b,{file_,i_,line_,col_}},"unterminated string");return;}take();out_.push_back({TokenKind::String,v,{b,{file_,i_,line_,col_}}});}
std::vector<Token> Lexer::scan(){static const std::unordered_map<std::string,TokenKind> kw={{"box",TokenKind::Box},{"line",TokenKind::Line},{"bool",TokenKind::Bool},{"cpx",TokenKind::Cpx},{"main",TokenKind::Main},{"if",TokenKind::If},{"else",TokenKind::Else},{"for",TokenKind::For},{"in",TokenKind::In},{"while",TokenKind::While},{"return",TokenKind::Return},{"print",TokenKind::Print},{"true",TokenKind::True},{"false",TokenKind::False}};while(peek()){auto s=i_;SourceLocation b{file_,i_,line_,col_};char c=peek();if(c==' '||c=='\t'||c=='\r'){take();continue;}if(c=='/'&&peek(1)=='/'){while(peek()&&peek()!='\n')take();continue;}if(c=='\n'){take();if(parens_==0)token(TokenKind::NewLine,s,b);continue;}if(c=='"'){stringToken(s,b);continue;}if(std::isalpha((unsigned char)c)||c=='_'){take();while(std::isalnum((unsigned char)peek())||peek()=='_')take();auto x=src_.substr(s,i_-s);auto it=kw.find(x);token(it==kw.end()?TokenKind::Identifier:it->second,s,b);continue;}if(std::isdigit((unsigned char)c)){take();while(std::isdigit((unsigned char)peek()))take();bool fl=false;if(peek()=='.'){fl=true;take();if(!std::isdigit((unsigned char)peek()))d_.error({b,{file_,i_,line_,col_}},"invalid number");while(std::isdigit((unsigned char)peek()))take();}token(fl?TokenKind::Floating:TokenKind::Integer,s,b);continue;}auto one=[&](TokenKind k){take();token(k,s,b);};switch(c){case'+':one(TokenKind::Plus);break;case'-':one(TokenKind::Minus);break;case'*':one(TokenKind::Star);break;case'/':one(TokenKind::Slash);break;case'(':++parens_;one(TokenKind::LParen);break;case')':--parens_;one(TokenKind::RParen);break;case'{':one(TokenKind::LBrace);break;case'}':one(TokenKind::RBrace);break;case',':one(TokenKind::Comma);break;case';':one(TokenKind::Semicolon);break;case'=':take();if(peek()=='='){take();token(TokenKind::EqEq,s,b);}else token(TokenKind::Assign,s,b);break;case'!':take();if(peek()=='='){take();token(TokenKind::NotEq,s,b);}else d_.error({b,b},"unexpected '!'");break;case'<':take();if(peek()=='='){take();token(TokenKind::LessEq,s,b);}else token(TokenKind::Less,s,b);break;case'>':take();if(peek()=='='){take();token(TokenKind::GreaterEq,s,b);}else token(TokenKind::Greater,s,b);break;default:take();d_.error({b,{file_,i_,line_,col_}},"invalid character");}}SourceLocation e{file_,i_,line_,col_};out_.push_back({TokenKind::Eof,"",{e,e}});return out_;}}
